// Package toolmeta holds the metadata table for the MCP tools registered
// by the Pulse MCP layer. It is the single public source of truth for tool
// identity — name + description records — imported by BOTH the descriptor
// package (to mirror records into the manifest payload) and the MCP core
// (for its catalog), without either taking a dependency on the other.
//
// The package is pure data: it imports no MCP SDK and no execution package,
// which lets descriptor source the tool list without producing an import
// cycle (descriptor is itself imported by the MCP layer, which depends on
// the root pulse package). The mcp/gosdk adapter's RegisteredTools() mirrors
// Names(), keeping these values in lockstep with server registration.
package toolmeta

// Tool name constants. Kept in alphabetical-by-constant order so the
// Meta() slice can be sorted by Name for deterministic manifest output
// while the constants themselves remain easy to maintain.
const (
	ToolInspect        = "pulse_inspect"
	ToolCohortsList    = "pulse_cohorts_list"
	ToolPredict        = "pulse_predict"
	ToolProcess        = "pulse_process"
	ToolProcessChain   = "pulse_process_chain"
	ToolCompose        = "pulse_compose"
	ToolSample         = "pulse_sample"
	ToolFacet          = "pulse_facet"
	ToolFacetSchema    = "pulse_facet_schema"
	ToolLookup         = "pulse_lookup"
	ToolSkillsList     = "pulse_skills_list"
	ToolSkillsGet      = "pulse_skills_get"
	ToolManifest       = "pulse_manifest"
	ToolExamplesSearch = "pulse_examples_search"
	ToolExamplesGet    = "pulse_examples_get"
	ToolErrorsLookup   = "pulse_errors_lookup"
	ToolImport         = "pulse_import"
	ToolDedup          = "pulse_dedup"
	ToolMaterialize    = "pulse_materialize"
	ToolRake           = "pulse_rake"
	ToolDrop           = "pulse_drop"
	ToolImportsList    = "pulse_imports_list"
	ToolLabelTables    = "pulse_label_tables"
	ToolLabelResolve   = "pulse_label_resolve"
	ToolRangeTables    = "pulse_range_tables"
	ToolLookupTables   = "pulse_lookup_tables"
	ToolRecommend      = "pulse_recommend"
	ToolExplain        = "pulse_explain"
)

// Description constants for the registered tools.
const (
	DescInspect        = "CALL TO SEE A COHORT'S FIELDS AND TYPES WITHOUT RUNNING A REQUEST. Read header and schema of a .pulse file without touching record data. Returns the field list (name, type, nullable, dictionary contents for categorical fields), record count, and format metadata.\n\nrecord_count is DERIVED (payload bytes / record stride), so a cohort whose payload is not a whole multiple of the stride reports the FLOOR. That case carries a coded ENCODING_INVALID entry in the additive `warnings` array with record_stride and trailing_bytes in its details; a clean read emits no `warnings` key at all. Read it — a truncated tail is invisible in the count itself.\n\nOptional `joins` [{right, as}] names the cohorts later requests join: on a server binding tools on inspect, the rebound request tools' field enums add each target's joined names (as + field) and joins[].on[].right_field its fields. Inspect output is unchanged."
	DescCohortsList    = "CALL FIRST WHEN YOU DO NOT KNOW WHICH COHORT HOLDS THE DATA. List every .pulse cohort under this server's data directory, in every subdirectory, sorted by path. Each entry: `path` (relative to the data directory: pass it as is as the request's cohort `filename`, or pulse_inspect `path`, with no `data_dir`), `record_count`, `fields` [{name, type, nullable}], `shard_archive` and `shard_count`, and `managed` plus `handle` for a managed import. Reads each file's header and schema only, never a record; sidecars, hidden files and the shards inside an archive are not listed, and listing does not extend a managed import's expiry. A .pulse file that cannot be read is still listed, with its coded `error` and no fields. Optional `dir` lists one subdirectory (relative to the data directory) only. Next, pulse_inspect one cohort for its dictionaries and field descriptions."
	DescPredict        = "CALL BEFORE STORING OR EXECUTING A HAND-AUTHORED OR GENERATED REQUEST. Validate a processing request against a cohort schema without executing. Returns the same diagnostics execution would emit on shape error (PULSE_REQUEST_UNKNOWN_FIELD, PULSE_FIELD_TYPE_UNSUPPORTED, etc.) plus the normalized request, streamability flag, and the defaults the engine applied; the coded `errors` / `warnings` behind a `valid: false` ride beside the result at the root. Cheap: it reads only the cohort header + schema.<!-- feature: capability:compose --> To predict a pulse_compose body, send it alone under `composed` (beside any other key it is SERVICE_VALIDATION); its verdict comes back under `composed` beside `errors` / `warnings`.<!-- /feature --><!-- feature: capability:facet --> To predict a pulse_facet_schema body, send it alone under `facet` (beside any other key it is SERVICE_VALIDATION); its verdict comes back under `facet` beside `errors` / `warnings`.<!-- /feature --><!-- feature: capability:process_chain --> To predict a pulse_process_chain body, send it alone under `chain` (beside any other key it is SERVICE_VALIDATION); its verdict comes back under `chain` beside `errors` / `warnings`.<!-- /feature -->"
	DescProcess        = "CALL TO RUN ONE VALIDATED REQUEST AGAINST A COHORT. Execute a pre-built processing request against an existing cohort. Supports the full operator catalog — aggregations, attributes, filterers, groupers, windows, features, regressions (with optional `resample` / `selection` modifiers), statistical tests, and matrices (`vectors` names a reusable list of numeric fields; `matrices` runs MAT_COVARIANCE or MAT_CORRELATION (Pearson) over a vector or inline `fields`, results under `matrices` in the response). A `matrices` slot (MAT_COVARIANCE / MAT_CORRELATION) is refused with PULSE_MATRIX_UNSUPPORTED_SOURCE on a request that also carries `joins`, and with PULSE_MATRIX_HOST_CONFLICT on a `crosstab` request — run the matrices as their own request.\n\nDO NOT author request bodies from memory, external documentation, or by reading source code — those may be out of date for this deployment. Before calling pulse_process, call pulse_examples_search to find a similar runnable example and pulse_examples_get to clone its body, OR call pulse_manifest for the operator catalog. The manifest + example library are the authoritative request-shape reference.\n\nNOTE: request slot keys differ from the manifest's operator-catalog field names. Grouping operations go under the \"groups\" key (NOT \"groupers\") and aggregations under \"aggregations\" (NOT \"aggregators\"); the catalog names \"groupers\"/\"aggregators\" only list the available GROUP_*/AGG_* operators. An unknown key at any depth is refused, never dropped: PULSE_REQUEST_UNKNOWN_FIELD names it, its location (details.path, e.g. sort[0].direction) and a 'did you mean' suggestion. A `union` ([{cohort, label}]) in place of `cohort` reads several cohorts as one record stream, each record tagged with its member label in the virtual categorical union_source_field (default _source) — group, filter, test or regress on it like any field (skill cohort-union)."
	DescCompose        = "CALL TO RUN SEVERAL REQUESTS IN ONE ROUND-TRIP. Each entry of `requests` is a pulse_process body against the same or a different cohort — common for ecological-regression patterns (slot 1 aggregates, slot 2 regresses over aggregates) and any multi-question authoring loop.\n\nReturns `{responses, overlays}`: `responses` holds one pulse_process result per `requests[i]`, in order; `overlays` holds one executed layer per `overlays[i]`, in order, and is omitted when the request carries no compose overlays. Each slot's `matrices` (MAT_COVARIANCE / MAT_CORRELATION, with its `vectors`) runs per slot and lands on that slot's response; a slot combining `matrices` with `joins` or `crosstab` is refused (PULSE_MATRIX_UNSUPPORTED_SOURCE / PULSE_MATRIX_HOST_CONFLICT) like a standalone request. A slot's `return` shapes that slot's response; a top-level `return` (`overlays…` paths only) shapes `overlays` after the fold and adds `returned`. Any slot may read a `union` in place of its `cohort`; the member label rides the virtual union_source_field (default _source), so one slot grouped by it replaces one slot per cohort."
	DescProcessChain   = "CALL WHEN EACH STAGE SHOULD READ THE PREVIOUS STAGE'S OUTPUT ROWS. Execute a source-rooted LINEAR CHAIN of processing stages: stage N+1 receives stage N's output rows as its input cohort. Collapses N round-trips into one. Every stage may use only mergeable aggregators, mergeable groupers and row-local attributes; the manifest's `process_chain` block lists them and its rejection rules (on a categorical field AGG_MODE chains the dictionary index, not the label; ATTR_FORMULA's total(expr) runs two-phase per stage). Windows, features, statistical tests, regressions, two-pass attributes and non-mergeable aggregators / groupers are refused with PULSE_CHAIN_NOT_MERGEABLE. Only stage 0 may carry `matrices` (MAT_COVARIANCE / MAT_CORRELATION, computed over the cohort rows and returned on stage 0's response, never passed to the next stage); a later stage's `matrices` is refused with PULSE_MATRIX_UNSUPPORTED_SOURCE. Fall back to pulse_compose or per-stage pulse_process. Each stage's output schema is synthesised: grouper keys become categorical_u32 fields, aggregator outputs f64 fields. Stage 0's request supplies the source cohort; later stages ignore their inner cohort field. A stage's `return` shapes that stage only after the whole chain ran (the next stage still reads its full rows); `final` follows the last stage's. A root `union` in place of `cohort` is read as stage 0's source, each record tagged with its member label in union_source_field (default _source)."
	DescSample         = "CALL TO EYEBALL A FEW RAW ROWS OF A COHORT. Returns up to N rows — a diagnostic / preview tool, typically after running a request. A `union` in place of `path` samples several cohorts read as one, rows in member order, each carrying its member label in union_source_field (default _source)."
	DescFacet          = "CALL TO LIST THE DISTINCT VALUES OF ONE FIELD. Diagnostic / discovery tool — for example, run it before authoring a FILTER_INCLUDE. For multi-field summaries with counts, null tallies, numeric stats, percentiles, histograms, or additive contribution counts, prefer pulse_facet_schema."
	DescFacetSchema    = "CALL TO SUMMARISE SEVERAL FIELDS AT ONCE WITH COUNTS, NULLS, STATS OR HISTOGRAMS. Multi-field rich facet endpoint. Returns per-field summaries (discrete value/count lists with null tallies for categorical/boolean/geo fields; streaming statistics — count, sum, min, max, mean, stddev — for numeric fields), with optional `numeric_percentiles` (forces a buffered per-field sort), `include_histogram` + `histogram_range` + `histogram_bins` for fixed-width binning, `discrete_top_k` truncation, and `additive_fields` contribution counts that strip the field's own filter clauses so you can report 'if I added value V to my filter on F, this is the population that survives'. Filterers reuse the standard FILTER_* surface. Use this instead of repeated pulse_facet calls when summarising more than one field, when you need counts (not just distinct values), or when building a faceted UI. A `union` in place of `cohort` summarises several cohorts read as one; facet union_source_field (default _source) to count records per member."
	DescLookup         = "CALL TO FETCH ROWS BY EXACT KEY FROM A COHORT WITH A PREBUILT INDEX. Resolve a point lookup (single-key or composite) against a cohort's prebuilt sidecar index — O(1) row addressing instead of a full scan. Supply either field+value (single-key convenience) or an ordered keys[] tuple (composite key, order must match the index's build-time key-field order); return_columns projects the output (empty = every schema field). multiplicity controls duplicate-key handling: 'assert_unique' (default; errors with PULSE_LOOKUP_AMBIGUOUS on >1 match), 'first' (deterministic lowest row-id, never errors on multi-match), or 'all' (every matching row, ascending row-id). Requires a sidecar index built with `pulse index build` or `Pulse.BuildIndex`; returns PULSE_INDEX_MISSING when none exists for the requested key fields, PULSE_INDEX_STALE when the cohort changed since the index was built (on a shard archive, also when a shard is not covered by the index — details.shards_uncovered), and PULSE_LOOKUP_NOT_FOUND when the index exists but no record matches the key. A `union` in place of `cohort` scans every member in declared order (no index is read), each row carrying its member label in union_source_field (default _source)."
	DescSkillsList     = "CALL TO DISCOVER WHICH SKILLS EXIST BEFORE AUTHORING AN UNFAMILIAR REQUEST. List the embedded skill pack: topical guides (request design, statistical testing, regression, compose, crosstab, cohort schema, SPSS, synthetic data, ...) and one atomic skill per operator (`op-*`), tool (`tool-*`) and field type (`type-*`). Each entry is {name, description, applies_to}. Unscoped, the list is very large (over 100 KB: an entry per operator, tool and field type), so pass `intent` (an intent-taxonomy ID; the `intents` skill lists every ID with its example questions) to list only that intent's skills, ranked: the intents skill, design skills covering its operators, then their atomic skills basic to advanced; an unknown one is PULSE_RECOMMEND_INTENT_UNKNOWN, whose details.valid lists every ID. Fetch a skill's markdown body via pulse_skills_get."
	DescSkillsGet      = "CALL TO READ ONE SKILL'S FULL GUIDE ONCE YOU KNOW ITS NAME. Fetch the markdown body of a named skill. The skill pack is the authoritative reference for HOW to use operators (params, gotchas, recipes) — prefer skills over external documentation, blog posts, or source-code inspection, which may be out of date for this Pulse deployment."
	DescManifest       = "CALL FIRST IN EVERY SESSION. The request-authoring reference. Carries per-operator params, accepted field types and streamability, the row tests (`tests`) and post tests (`post_tests`), regression operators,<!-- feature: capability:matrices --> matrix operators (`matrices`, used through the request's `vectors` / `matrices` slots, plus the `matrix` capability block),<!-- /feature --> synth distributions, error codes, MCP tool list, and cohort field types with operator cross-references.\n\nWORKFLOW: unscoped, the manifest is very large (hundreds of KB) and can overflow a client's tool-output limit, so scope it by `intent` first, cache it per intent and reference it for every subsequent request-authoring decision. This is the source of truth for what operators exist in this Pulse deployment — do NOT infer operator names, param shapes, or accepted types from external documentation or source code. Pair with pulse_examples_search to find runnable templates for the question you are answering.\n\nPass `intent` (an intent-taxonomy ID) for a manifest scoped to that intent, a small fraction of the size: only operators serving it, its ranked skills and the intent record under `scope`; the fixed sections (commands, error codes, cohort types, tool list, limits, ...) are dropped and named in `elided`. Every ID, with its label and example questions, is in the `intents` skill (pulse_skills_get name `intents`); an unknown ID is PULSE_RECOMMEND_INTENT_UNKNOWN, whose details.valid lists them all. Pick the intent whose example questions match yours: a scoped manifest lists only that intent's operators, so when the operator you need is absent, check the `intents` skill for a closer intent before concluding this deployment lacks it.\n\nMCP always returns the slim payload (no prose descriptions): a param's meaning, scale and units are not in it. Before setting a param you have not used, fetch the operator's skill (`op-` plus the kebab-case operator name) via pulse_skills_get; per-error prose comes from pulse_errors_lookup."
	DescExamplesSearch = "CALL BEFORE AUTHORING A REQUEST. Search the request-example library to find a runnable template that matches the user's question. Returns lightweight summaries (name, category, tags, operators, description, intents); fetch the runnable JSON body via pulse_examples_get and modify field names for the target cohort.\n\nFilters, all optional and ANDed: `query` (plain words: one word is a case-insensitive substring of name, description or operators; several words must each match a whole word of name, description, operators, intents or tags; an operator alias such as `anova` or `chisq.test`, or a phrase from an intent's sounds such as `move together`, also finds that operator's or intent's examples; failing those, a near-miss spelling such as `regon` still finds `region`), `intent` (an intent-taxonomy ID such as `compare_groups`; an unknown one is PULSE_RECOMMEND_INTENT_UNKNOWN), `tags` (ANDed list of canonical taxonomy tags such as `time-series`, `experiment-analysis`, `tier-1-test`, `regression`, `ols`, `logistic`), and `category` (exact directory: `aggregations`, `attributes`,<!-- feature: capability:compose --> `compose`,<!-- /feature --><!-- feature: capability:crosstab --> `crosstab`,<!-- /feature --><!-- feature: capability:facet --> `facet`,<!-- /feature --> `features`, `filterers`, `groupers`,<!-- feature: capability:materialize --> `materialize`,<!-- /feature --><!-- feature: capability:matrices --> `matrices`,<!-- /feature --> `overlays`, `regression`, `tests`, `windows`).<!-- feature: capability:matrices, MAT_COVARIANCE, MAT_CORRELATION --> The `matrices` examples show MAT_COVARIANCE and MAT_CORRELATION over named `vectors`.<!-- /feature --><!-- feature: capability:compose --> The `compose` examples show a compose `sweep` expanded into slots.<!-- /feature -->\n\nThe library is this server's own: the shipped examples plus any the embedder registered, minus any that use a feature this server hides (those read as absent).\n\nPrefer this over inferring request shapes from documentation or source code — the shipped examples are curated, runnable, and stay in lockstep with the operator surface; embedder examples are validated the same way at startup."
	DescExamplesGet    = "CALL AFTER A SEARCH FINDS A MATCHING EXAMPLE, TO GET ITS RUNNABLE BODY. Fetch one request example from the request-example library by `name`. Returns the full record including `body`, a runnable request with the _meta annotation block stripped and every cohort named by its filename relative to this server's data directory (no `data_dir`); swap in the cohort (pulse_cohorts_list) and fields your question needs. Hand it straight to pulse_predict<!-- feature: capability:process --> or pulse_process<!-- /feature -->. Serves the same library as pulse_examples_search: embedder examples included, an example that uses a feature this server hides reads as not found."
	DescErrorsLookup   = "CALL WHEN A TOOL RETURNS AN ERROR CODE YOU NEED EXPLAINED. Look up Pulse error code metadata. Pass code=PULSE_XXX for full detail on one code. Pass domain=PULSE/ENCODING/PROCESSING/SERVICE/DATA/CLI to enumerate that domain. Pass query=\"text\" for keyword search across descriptions and fixups. The manifest carries only the code-name list — fetch detail here on demand to keep session context lean."
	DescImport         = "CALL TO BRING AN EXTERNAL DATA FILE INTO PULSE AS A COHORT. Import a tabular source file (csv, tsv, ndjson, jsonarray, parquet, arrow, excel, spss) into a managed .pulse handle, or pass through an existing .pulse file unchanged. Auto-detects format from the extension; override via `format`. SPSS `.sav` / `.zsav` sources are schema-AUTHORITATIVE: the file's own dictionary supplies every column type, nullability and categorical dictionary ORDER, so inference is skipped entirely — and the cohort's categorical dictionaries hold the SPSS numeric CODES, not the value labels (two codes may share a label, so a label-keyed dictionary would collapse them); resolve labels at output time with a label table. `pulse export spss` writes a `.sav` from a cohort, reproducing the source dictionary from the metadata sidecar the import wrote beside it. Managed handles live in $PULSE_DATA_DIR/imports/ with a TTL-tracked sidecar — every subsequent inspect/predict/process/sample/facet against the handle slides expiry forward. TTL accepts Go duration form (`24h`, `30m`, `3600s`, `1h30m`) plus day suffix (`7d`, `30d`) and `pin` for never-expire. Returns the handle, managed path, `format` (the written cohort's format: always `pulse`), `source_format` (the format the source was read as), row count, expiry, and a managed flag. Pulse-format sources skip the copy + sidecar; they pass through with managed=false.\n\nSPSS read knobs: `charset` overrides the encoding a `.sav` declares about itself and is the ONLY recourse for a file that is wrong about itself — a stale record 7/20 name, or a pre-Unicode file declaring nothing at all, which reads as strict UTF-8 and fails PULSE_SPSS_CHARSET_INVALID on its first 8-bit byte. It is ignored for every other format. There is deliberately NO missing-value mode here: the default is the fidelity-preserving split (numeric user-missing values are null in the analytic field, and a generated `<var>_missing` sibling field records why), and the only alternative discards those siblings — ask for that explicitly with `pulse import spss --spss-missing=null`.\n\nParent groups (denormalized joins): `groups` takes `[{key: [...], members: [...]}]` — each distinct member tuple is stored once and every row carries a 4-byte index, a smaller format 0x02 cohort; a member that varies within its key fails PULSE_GROUP_MEMBER_NOT_CONSTANT. Do not guess declarations: set `suggest_groups: true` to get measured `group_candidates` (ratio, resident dictionary bytes, projected size, verdict) whose key/members paste straight back as `groups`, then re-import with `overwrite: true`. Weak groups are reported as coded `group_warnings` (PULSE_GROUP_TOO_NARROW dropped, PULSE_DEDUP_LOW_RATIO written; default floor 2 rows per tuple), never failures; per-group figures ride `groups`.\n\nExplicit schema: `schema` takes `[{name, type, nullable, description}]` (the `pulse import --schema` document; omit it to infer). Fields match source columns BY NAME, never position, and each mismatch is refused before any row is read with its own code: PULSE_IMPORT_SCHEMA_FIELD_MISSING, _COLUMN_UNMAPPED, _DUPLICATE, _KEY_LATE, _TYPE_UNKNOWN, _INVALID. `ignore_extra: true` drops unnamed source columns instead. `float` picks the inferred float width: `f64` (default, exact decimals) or `f32`.\n\nNative vectors (wide-format batteries such as rate_a..rate_e): `vectors` folds sibling columns into ONE vec_f64 / vec_f32 field — `[\"brand_rating:/^rate_(.*)$/\"]` (regex: matching columns in source order, first capture group labels each element) or `[\"brand_rating:rate_a,rate_b,rate_c\"]` (listed order); `vector_kinds` adds `[\"brand_rating:scale:1:7\"]`. A bare name (`[\"emb\"]`, `[\"emb:f32\"]`) reads the NATIVE list column of that name (Arrow FixedSizeList / LIST, Parquet LIST, an NDJSON / JSON array) as a vec_f64 / vec_f32 field whose dim is the list length; csv / tsv / excel refuse it. 2..1024 columns or elements; all elements empty (or null) = null vector, some = NaN. Bad declarations fail PULSE_IMPORT_VECTOR_INVALID before any row, and so does a variable-length, non-numeric or out-of-range list; requests then name the vector field directly in vector slots."
	DescDedup          = "CALL WHEN A COHORT REPEATS PARENT ATTRIBUTES ON EVERY CHILD ROW. Deduplicate an EXISTING single-file .pulse cohort: a denormalized join repeats each parent's attributes on every child row, and declaring the parent as a group (`groups`: [{key, members}], the pulse_import shape) stores each distinct parent tuple once with a 4-byte index per row — a smaller format 0x02 cohort that answers every request exactly as the original does. Do not guess declarations: first call with `suggest_groups: true` alone (READ-ONLY) to get measured `group_candidates` (ratio, resident dictionary bytes, projected size, verdict), then call again with `groups` set to the suggested key/members. With `out` the result goes to a new path and the original is untouched; without it the cohort is rewritten IN PLACE (atomic — any failure, including PULSE_GROUP_MEMBER_NOT_CONSTANT when a member varies within its key, leaves it unchanged). Weak groups are reported as coded `group_warnings` (PULSE_GROUP_TOO_NARROW dropped, PULSE_DEDUP_LOW_RATIO written; default floor 2 rows per tuple). An in-place rewrite lists each sidecar it invalidated (point-lookup index, SPSS metadata) under `invalidated_sidecars` with its rebuild command and rebuilds nothing. Shard archives are refused with SERVICE_VALIDATION."
	DescMaterialize    = "CALL WHEN A LATER REQUEST MUST READ A WINDOW, FEATURE OR ATTRIBUTE OUTPUT AS AN ORDINARY FIELD. Write a NEW .pulse cohort (`out`, relative to PULSE_DATA_DIR; a single file unless `output.shards`) holding every filter-passing record of `request`'s cohort: the source fields verbatim, then one nullable f64 field per derived output of the request (features, attributes, windows) in pipeline order, each with a generated description. Derived values exist only inside the request that computes them, so a regression, grouper, filter or join over one needs this step first; then point the next request at `out`. `request` takes the pulse_process body but only the cohort, label, features, filterers, attributes, windows, sort (orders the output rows; keys may name derived fields), weight, time_zone and disable_components slots: any other slot is PULSE_MATERIALIZE_SLOT_UNSUPPORTED (details.slot), a request with no derived field PULSE_MATERIALIZE_NO_DERIVED, and an unknown key PULSE_REQUEST_UNKNOWN_FIELD. An `output` block in `request` lays out the written cohort — `columns` [{from, as, description, nullable}] (exactly these, in order) XOR `exclude`, applied after every other slot, so a request may then carry no derived field; `shards: {max_records}` writes a shard archive, `elide_constants: true` stores constant fields once; `groups` [{key, members}] declares parent groups over the written names (absent keeps each source group whose members are written unchanged, warning PULSE_MATERIALIZE_GROUP_NOT_INHERITED for one it cannot; `[]` writes none) — refused when malformed with PULSE_MATERIALIZE_OUTPUT_INVALID / _UNKNOWN_COLUMN / _DUPLICATE, a null in a `nullable: false` field fails the run with PULSE_MATERIALIZE_OUTPUT_NULL. Every refusal happens before anything is written; the write is atomic. An existing `out` is refused with SERVICE_VALIDATION unless `overwrite: true`, which lists each sidecar it invalidated under `invalidated_sidecars` (with its rebuild command) beside a PULSE_MATERIALIZE_SIDECARS_INVALIDATED warning. Returns target, records, derived_columns, shards, elided_constants, groups (each group's gate verdict), warnings. `predict: true` validates without writing (no `out` needed), reading the source's header and schema only: the answer is under `predict` — valid, the output fields (name, type, nullable, description, from, derived), derived_columns, the data-dependent risks, the container plan (with its parent groups) and the coded errors / warnings, each refusal with the run's own code and details."
	DescRake           = "CALL TO COMPUTE SURVEY WEIGHTS THAT MAKE A SAMPLE MATCH KNOWN POPULATION SHARES. Rim weighting (raking) to one or more target margins, or cell weighting (post-stratification) when a margin joins several fields: writes a NEW single-file .pulse cohort (`out`, relative to PULSE_DATA_DIR) holding every source record and field verbatim plus a nullable f64 weight field (`weight_field`, default rake_weight). Targets are inline in `margins`: `{field, targets: {category: share}}` or `{fields: [..], cells: [{values: [..], target}]}`, as shares (sum 1 or 100) or `targets_as: counts`. Optional `by` rakes each group (a survey wave) separately; `base_weight` starts from a design weight; `min_weight` / `max_weight` cap weights relative to the mean. The output is a PROBABILITY weight: name it as a later request's `weight`. Returns iterations, converged, residual, per-margin observed / target / achieved shares, and the Kish efficiency (n_eff, deff_kish — the unequal-weighting design effect only, never a complex-sample one). Refusals happen before anything is written: PULSE_RAKE_INVALID (details.reason), PULSE_RAKE_UNKNOWN_CATEGORY, PULSE_RAKE_MISSING_VALUE, PULSE_RAKE_UNTARGETED_CATEGORY, PULSE_RAKE_EMPTY_CELL; an existing `out` without `overwrite: true` is SERVICE_VALIDATION. Stopping at max_iter still writes, with PULSE_RAKE_NOT_CONVERGED."
	DescDrop           = "CALL TO DELETE A MANAGED IMPORT YOU NO LONGER NEED. Drop a managed-import handle from the pool, deleting the .pulse file and its sidecar. Errors with PULSE_IMPORT_SOURCE_MISSING when the handle is unknown. Pulse-format passthroughs are unaffected (they were never managed)."
	DescImportsList    = "CALL TO SEE WHICH MANAGED IMPORTS EXIST AND WHICH HAVE EXPIRED. List every managed-import handle currently in the pool with its sidecar metadata: source path, source format, imported_at, expires_at, ttl, expired flag, pinned flag. Listing sweeps nothing: an expired entry is flagged `expired: true` so you can decide whether to drop or re-import it. It lists managed imports ONLY, never the other cohorts in the data directory: to see every cohort, imported or not, call pulse_cohorts_list."
	DescLabelTables    = "CALL TO FIND WHICH CATEGORICAL FIELDS CAN BE RESOLVED BY DISPLAY NAME. List the registered label tables (ID→display-name dictionaries for categorical fields). Returns each table's name, row count, and whether it is enumerable (reverse-searchable). Run it before pulse_label_resolve. Output surfaces already render these labels automatically; this tool and pulse_label_resolve are for the INPUT direction — turning a user-supplied name into the raw categorical key a filter / grouper needs."
	DescRangeTables    = "CALL TO FIND WHICH NAMED RANGE SETS EXIST BEFORE GROUPING OR FILTERING BY ONE. List the registered range tables (named, reusable sets of labeled ranges — date tables such as fiscal quarters or campaign windows, numeric tables such as a train/holdout split or score bands). Returns each table's name, kind (date | numeric), range count, and the ordered {label, start, end} ranges themselves (ranges: ISO date literals, inclusive; numeric_ranges: numbers, half-open [start, end); an omitted start/end is an open bound). A GROUP_DATE_RANGES grouper or FILTER_DATE_RANGES filter references a date table by name, a GROUP_NUMERIC_RANGES grouper a numeric one — the INPUT direction, turning a table name into the usable range set; a table of the other kind is refused PULSE_RANGE_TABLE_KIND_MISMATCH. Returns an empty list (never an error) when no range tables are registered; tables are supplied programmatically via Options.Extensions.RangeTables or loaded from the PULSE_RANGE_TABLES_DIR directory at pulse.New time."
	DescLookupTables   = "CALL TO FIND WHICH LOOKUP TABLES EXIST AND THEIR KEY AXES BEFORE WRITING A LOOKUP() CALL. List the registered lookup tables — named numeric tables an expression reads with lookup(\"table\", k1, k2, …), such as a rate grid. Returns each table's name, description, has_rows_data, cell_count (the number of cells of a static table; absent for a function-driven table, whose cells cannot be counted), keys (the declared axes in argument order, each a name plus its inline values or the range_table whose labels are its values; empty when the table declares none and its keys are free-form) and complete (every axis combination has a cell). Never returns a cell value. A key off its axis, or an unlisted combination of a sparse table, misses with PULSE_LOOKUP_MISS; a range-table axis is fed by range_label(table, x). Returns an empty list (never an error) when no lookup tables are registered; tables are supplied programmatically via Options.Extensions.LookupTables or loaded from the PULSE_LOOKUP_TABLES_DIR directory at pulse.New time."
	DescRecommend      = "CALL WHEN YOU KNOW THE KIND OF QUESTION BUT NOT THE REQUEST. Turns an intent ID (the `intents` skill lists every ID with its example questions) into ranked draft requests instead of hand-built JSON. Without `cohort` the drafts are UNBOUND skeletons: every value you must supply is a \"<placeholder>\" string named after its wire key and listed in `placeholders` — useful for planning before data exists. With `cohort` (a .pulse path) the drafts are BOUND to the cohort's own fields and each one has passed pulse_predict; a draft with `bound: false` still `needs` a value only you can choose (a success value, a reference mean, a model family). `fields` pins hint fields to roles (cohort only); `level` (basic / intermediate / advanced) ranks that level first; `limit` caps the list (default 10; `truncated` and `candidates_considered` say what was cut). Each draft carries `why`, the intent's field `shapes`, predict `advisories`, `alternatives` and `follow_ups`. A non-analytic intent (prepare, simulate, lookup) or one nothing serves returns an empty `recommendations` list plus `routes_to` — the tooling that answers it — never an error. An unknown intent is PULSE_RECOMMEND_INTENT_UNKNOWN (details.valid lists every ID); a bad field hint is SERVICE_VALIDATION; an unreadable cohort is SERVICE_RESOURCE. Reads the cohort header, schema and sidecar only."
	DescExplain        = "CALL TO SAY IN PLAIN WORDS WHAT A REQUEST WILL DO, OR WHAT A RESULT FOUND — instead of reading p-values yourself. Set exactly ONE root. Request mode: `request` (a pulse_process body), `composed`, `chain`, `facet` or `sample`; nothing runs — a root naming a cohort is predict-checked (header and schema only), so `valid`, `refusals`, `defaults_applied` and `advisories` say what would happen. Response mode: `response` (a pulse_process result), `composed_response`, `chain_response` or `facet_result`, ideally with the request that produced it beside it (`request` / `composed` / `chain` / `facet`) — without it an aggregation is described by count only and a caveat says the reading is partial. Pass results exactly as Pulse returned them: a null figure is undefined and stays undefined. Output: `summary` (one sentence), `findings[]` (per test, regression coefficient and fit, overlay layer, matrix and aggregation: `slot`, `verdict` — evidence_of_difference / no_evidence_of_difference / …_association / …_effect / descriptive / not_computable — read at the result's own alpha, adjusted when a correction ran; `strength_band` only with its `convention`; the `numbers` it rests on), `steps[]` in request mode, and `caveats` — relay them, never drop them. A non-significant result is \"no evidence of\" a difference, never evidence of none. `detail: full` adds narrative `sentences`, glossary refs, follow-ups and the tests' assumptions. Operator mode: `operator` alone (an operator name) returns `validation` — the external `references` its figures are pinned to (`against`, `tolerance`, `tests`), a stated `gap`, a pinned `weight_refusal` and NIST `certification` digits — so you can say how far to trust a figure. Zero or several roots, a companion beside the wrong result, or an unknown detail is SERVICE_VALIDATION; an unreadable cohort is SERVICE_RESOURCE."
	DescLabelResolve   = "CALL WHEN THE USER NAMES A CATEGORY VALUE BY ITS DISPLAY LABEL. Reverse-resolve a human-readable name — including a minor misspelling — to the raw categorical key(s) a Pulse filter or grouper expects. Labels are output-only — filter / group / sort keys operate on the raw categorical value — so when a user names a brand, category, region, etc., call this to get the key before authoring a FILTER_INCLUDE or GROUP_CATEGORY. Args: table (a name from pulse_label_tables), query (the name to search; typo-tolerant), and optional limit (default 10). Returns {key, value, score} ranked by score, a confidence in [0,1]: 1.0 exact (or exact-key), ~0.9+ prefix/near-typo, lower is fuzzy (edit-distance + trigram). Matching normalizes case and punctuation. Decision rule: if the top score is high (>=0.9) and clearly ahead of the next, use it; if the best score is low or several are close, present the top names to the user and ask which they meant rather than guessing. An empty query returns the first rows (browse mode, score 0)."
)

// ToolMeta is the canonical (name, description) record for one registered
// MCP tool. A Description may carry feature fences — the skill-pack
// grammar, `<!-- feature: NAME[, NAME…] -->…<!-- /feature -->`, around a
// clause about one feature inside a sentence about others — so a
// profiled instance drops the clause, not the sentence. Never serve a
// Description raw: the MCP registration renders it through
// descriptor.ProseScrub.Text and the manifest through
// descriptor.RenderProseFences (markers stripped on every instance).
type ToolMeta struct {
	Name        string
	Description string
}

// Meta returns the canonical list of MCP tool metadata. Order matches
// gosdk.RegisteredTools() for deterministic documentation scans.
func Meta() []ToolMeta {
	return []ToolMeta{
		{Name: ToolInspect, Description: DescInspect},
		{Name: ToolCohortsList, Description: DescCohortsList},
		{Name: ToolPredict, Description: DescPredict},
		{Name: ToolProcess, Description: DescProcess},
		{Name: ToolProcessChain, Description: DescProcessChain},
		{Name: ToolCompose, Description: DescCompose},
		{Name: ToolSample, Description: DescSample},
		{Name: ToolFacet, Description: DescFacet},
		{Name: ToolFacetSchema, Description: DescFacetSchema},
		{Name: ToolLookup, Description: DescLookup},
		{Name: ToolSkillsList, Description: DescSkillsList},
		{Name: ToolSkillsGet, Description: DescSkillsGet},
		{Name: ToolManifest, Description: DescManifest},
		{Name: ToolExamplesSearch, Description: DescExamplesSearch},
		{Name: ToolExamplesGet, Description: DescExamplesGet},
		{Name: ToolErrorsLookup, Description: DescErrorsLookup},
		{Name: ToolImport, Description: DescImport},
		{Name: ToolDedup, Description: DescDedup},
		{Name: ToolMaterialize, Description: DescMaterialize},
		{Name: ToolRake, Description: DescRake},
		{Name: ToolDrop, Description: DescDrop},
		{Name: ToolImportsList, Description: DescImportsList},
		{Name: ToolLabelTables, Description: DescLabelTables},
		{Name: ToolLabelResolve, Description: DescLabelResolve},
		{Name: ToolRangeTables, Description: DescRangeTables},
		{Name: ToolLookupTables, Description: DescLookupTables},
		{Name: ToolRecommend, Description: DescRecommend},
		{Name: ToolExplain, Description: DescExplain},
	}
}

// Names returns the tool identifier list (no descriptions) in the same
// order as Meta(). Stable.
func Names() []string {
	meta := Meta()
	out := make([]string, len(meta))
	for i, m := range meta {
		out[i] = m.Name
	}
	return out
}
